 static Material Material(string name,Color color){string path="Assets/TruckHockey/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}if(name=="Red lines"||name=="Blue lines")m.shader=Shader.Find("Universal Render Pipeline/Unlit");m.color=color;m.SetFloat("_Smoothness",name=="Ice"?.42f:.2f);EditorUtility.SetDirty(m);return m;}
 static GameObject Box(string name,Vector3 pos,Vector3 size,Material mat,bool coll=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!coll)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Circle(string name,Vector3 center,float radius,Material mat){var g=new GameObject(name);var l=g.AddComponent<LineRenderer>();l.useWorldSpace=true;l.loop=true;l.positionCount=64;l.startWidth=l.endWidth=.06f;l.sharedMaterial=mat;for(int i=0;i<64;i++){float a=i*Mathf.PI*2/64;l.SetPosition(i,center+new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius));}}
 static PhysicsMaterial Contact(string name,float restitution,float friction){string path="Assets/TruckHockey/Materials/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(m==null){m=new PhysicsMaterial(name){bounciness=restitution,dynamicFriction=friction,staticFriction=friction,bounceCombine=PhysicsMaterialCombine.Maximum,frictionCombine=PhysicsMaterialCombine.Minimum};AssetDatabase.CreateAsset(m,path);}var serialized=new SerializedObject(m);serialized.FindProperty("m_Bounciness").floatValue=restitution;serialized.FindProperty("m_DynamicFriction").floatValue=friction;serialized.FindProperty("m_StaticFriction").floatValue=friction;serialized.FindProperty("m_BounceCombine").intValue=(int)PhysicsMaterialCombine.Maximum;serialized.FindProperty("m_FrictionCombine").intValue=(int)PhysicsMaterialCombine.Minimum;serialized.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 public static GameObject TruckGeometry(Transform parent,float length){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Vehicles/Euro Truck by GR3D/SemiTruck.prefab");if(source==null)throw new Exception("NWH visual prefab missing");var copy=(GameObject)PrefabUtility.InstantiatePrefab(source);var visual=new GameObject("NWH GR3D visual geometry");visual.transform.SetParent(parent,false);foreach(var f in copy.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<MeshRenderer>();if(r==null||f.sharedMesh==null)continue;var p=new GameObject(f.name);p.transform.SetParent(visual.transform);p.transform.position=f.transform.position;p.transform.rotation=f.transform.rotation;p.transform.localScale=f.transform.lossyScale;p.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;p.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;}UnityEngine.Object.DestroyImmediate(copy);var rr=visual.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);float scale=length/Mathf.Max(b.size.x,b.size.z);visual.transform.localScale=Vector3.one*scale;visual.transform.localPosition=new Vector3(-b.center.x*scale,-b.min.y*scale-.2f,-b.center.z*scale);return visual;}
 public static Camera Camera(){var g=new GameObject("Arena Camera",typeof(Camera),typeof(AudioListener));var c=g.GetComponent<Camera>();c.orthographic=true;c.orthographicSize=10.5f;c.backgroundColor=new Color(.012f,.024f,.044f);c.clearFlags=CameraClearFlags.SolidColor;g.transform.position=new Vector3(0,19,-13);g.transform.LookAt(Vector3.zero);g.tag="MainCamera";var fit=g.AddComponent<SportsCameraFit>();fit.cameraTarget=c;fit.worldWidth=32;fit.worldHeight=20.5f;var sun=new GameObject("Arena key light").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.7f;sun.transform.rotation=Quaternion.Euler(52,-28,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.48f,.56f,.66f);return c;}
